import {initWarReports} from './observatorio-war-reports.mjs';
import {initConflictLayer} from './observatorio-conflicts.mjs';
export const violenceTypes={'1':'Con participación estatal','2':'Entre grupos no estatales','3':'Violencia contra civiles'};
const countries={'Ukraine':'Ucrania','Russia (Soviet Union)':'Rusia','Sudan':'Sudán','South Sudan':'Sudán del Sur','Myanmar (Burma)':'Myanmar','Yemen (North Yemen)':'Yemen','DR Congo (Zaire)':'RD del Congo','Central African Republic':'República Centroafricana','Afghanistan':'Afganistán','Algeria':'Argelia','Brazil':'Brasil','Cameroon':'Camerún','Ethiopia':'Etiopía','Haiti':'Haití','Iran':'Irán','Iraq':'Irak','Ivory Coast':'Costa de Marfil','Lebanon':'Líbano','Libya':'Libia','Mexico':'México','Moldova':'Moldavia','Morocco':'Marruecos','Niger':'Níger','Pakistan':'Pakistán','Peru':'Perú','Philippines':'Filipinas','Saudi Arabia':'Arabia Saudita','South Africa':'Sudáfrica','Spain':'España','Sweden':'Suecia','Syria':'Siria','Thailand':'Tailandia','Turkey':'Turquía','United States of America':'Estados Unidos','United Arab Emirates':'Emiratos Árabes Unidos'};
const topicNames={politica:'Política',deportes:'Deportes',conflictos:'Guerras y conflictos',economia:'Economía',ciencia:'Ciencia y ambiente',tecnologia:'Tecnología',salud:'Salud y sociedad',cultura:'Cultura'};
const categoryNames={'Wildfires':'Incendios','Severe Storms':'Tormentas','Floods':'Inundaciones','Drought':'Sequía','Dust and Haze':'Polvo y bruma','Snow':'Nieve','Temperature Extremes':'Temperaturas extremas','Sea and Lake Ice':'Hielo marino y lacustre','Volcanoes':'Volcanes','Landslides':'Deslizamientos','Earthquakes':'Sismos','Sismos':'Sismos'};
export const countryName=c=>countries[c]||c;
export const fold=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function selectMapRows(mode,{conflicts=[],events=[],newsEvents=[]},query='',category='all',days=30,now=Date.now()){
 const input=mode==='conflicts'?conflicts:mode==='climate'?events:newsEvents;
 return input.filter(e=>(mode==='conflicts'||Date.parse(e.date)>=now-days*86400000)&&(category==='all'||(mode==='news'?(e.topics||[]).includes(category):String(mode==='conflicts'?e.type:e.category)===category))&&fold([e.title,e.place,e.country,countryName(e.country),e.region,e.source,...(e.actors||[])].join(' ')).includes(fold(query)));
}
export function initMapExplorer({map,L,markers,baseLayer,esc,date,openEvent,addEvidence,readNews}){
 if(!map||!L)return null;
 const $=id=>document.getElementById(id);let warView='reports',mode='conflicts',catalog=null,catalogError=false,loading=false,selected=null,limit=50,state={events:[],newsEvents:[],sources:[]},tile=baseLayer;
 const dotLayer=L.layerGroup().addTo(map),canvas=L.canvas({padding:.3});markers.clearLayers();
 const catalogPanel=document.querySelector('.map-catalog'),catalogDetails=document.createElement('details');catalogDetails.id='map-catalog-details';catalogDetails.open=!matchMedia('(max-width:900px)').matches;const catalogSummary=document.createElement('summary');catalogSummary.textContent='Explorar y filtrar';catalogDetails.append(catalogSummary);while(catalogPanel.firstChild)catalogDetails.append(catalogPanel.firstChild);catalogPanel.append(catalogDetails);matchMedia('(max-width:900px)').addEventListener('change',e=>{catalogDetails.open=!e.matches});
 const warTools=document.createElement('div');warTools.className='war-tools';warTools.innerHTML='<label>Vista bélica<select id="war-view"><option value="reports">Ataques recientes · prensa</option><option value="events">Eventos documentados · UCDP</option><option value="groups">Conflictos agrupados</option></select></label><label>Desde<input id="war-from" type="date"></label><label>Hasta<input id="war-until" type="date"></label>';$('map-results').before(warTools);
 $('war-view').onchange=()=>{warView=$('war-view').value;selected=null;limit=50;$('map-category').value='all';setCategories();render();if(warView==='reports')reports.load();else loadCatalog()};for(const id of ['war-from','war-until'])$(id).onchange=()=>{limit=50;render()};
 const reports=initWarReports({db:window.auraClient,map,esc,date,addEvidence,readNews,render});
 const control=initConflictLayer({map,L,markers:null});$('map-territory').append(control.panel);control.panel.hidden=true;
 control.panel.querySelector('#conflict-signals').closest('label').hidden=true;

 const sourceLink=(href,label)=>`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
 function setCategories(){const cats=mode==='conflicts'?(warView==='reports'?[['preliminary','Reportes preliminares'],['confirmed','Confirmados · revisión editorial']]:Object.entries(violenceTypes)):mode==='news'?Object.entries(topicNames):[...new Set((mode==='climate'?state.events:state.newsEvents).map(e=>e.category))].sort().map(c=>[c,categoryNames[c]||c]);const previous=$('map-category').value;$('map-category').innerHTML='<option value="all">Todas</option>'+cats.map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join('');if(cats.some(([k])=>k===previous))$('map-category').value=previous;}
 function coverage(){
 if(mode==='conflicts'&&warView==='reports'){$('map-layer-stamp').textContent='Reportes de prensa · últimos 7 días · cobertura parcial · ubicaciones aproximadas';$('map-legend').textContent='● Ámbar: preliminar · ● Verde: confirmado tras revisión editorial';$('map-coverage').innerHTML=`<strong>Ataques recientes · noticias públicas</strong><p>${esc(reports.info?.coverage||'Consultando titulares…')}</p><p>Última consulta: ${reports.info?esc(date(reports.info.updatedAt)):'pendiente'}. ${reports.error||reports.info?.stale?(reports.rows.length?'La actualización falló; conservamos los reportes cargados.':'No se pudieron cargar los reportes; puedes reintentar.'):reports.info?.partial?'Algunas consultas no respondieron.':''}</p><p>La fecha de publicación no equivale a la fecha del ataque. Las ubicaciones son referencias del titular; los reportes sin lugar claro permanecen en la lista. Confirmado requiere revisión editorial y fuentes de respaldo visibles.</p><button id="retry-war">↻ Actualizar reportes</button>`;$('retry-war').onclick=reports.load;return;}

 $('map-layer-stamp').textContent=mode==='conflicts'?(catalog?'UCDP Candidate · '+catalog.metadata.period+' · '+catalog.metadata.countries+' países · preliminar':'UCDP Candidate · cargando cobertura'):mode==='climate'?'NASA EONET · 30 días | USGS · 7 días · cobertura global según catálogo':'Noticias del feed · publicación y fuente en cada registro · ubicaciones aproximadas';
  if(mode==='conflicts'){$('map-legend').innerHTML='<span style="color:#b75155">● Estatal</span> · <span style="color:#bf842d">● No estatal</span> · <span style="color:#8e5898">● Contra civiles</span> · '+(warView==='events'?'eventos candidatos':'puntos agregados');$('map-coverage').innerHTML=catalog?`<strong>UCDP Candidate · ${esc(catalog.metadata.period)}</strong><p>Cobertura global del conjunto: ${catalog.metadata.countries} países · ${catalog.metadata.eventCount.toLocaleString('es-CL')} registros. No es un inventario exhaustivo de todas las guerras actuales. ${warView==='events'?'Eventos individuales de violencia organizada: no equivalen a todos los ataques ni a alertas en vivo. La precisión varía por registro.':'Puntos centrales agregados, no frentes ni ataques individuales.'}</p><details><summary>Fecha, cobertura y método</summary><p>Versión ${esc(catalog.metadata.version)} · recuperado ${esc(date(catalog.metadata.retrievedAt))}. Comprobación automática cada 6 horas; ${catalog.metadata.refresh?'última comprobación '+esc(date(catalog.metadata.refresh.checkedAt))+' · '+(catalog.metadata.refresh.status==='ok'?'fuente consultada':'actualización fallida; conservamos los últimos datos válidos'):'primera comprobación pendiente'}. No es tiempo real. ${esc(catalog.metadata.method)}</p><p>${catalogError?'No se pudo comprobar la versión publicada; se conserva la cargada. ':''}${esc(catalog.metadata.citation)} · CC BY 4.0</p>${sourceLink(catalog.metadata.docs,'Datos y metodología UCDP')} · <a href="/data/conflict-catalog.json" download>Descargar catálogo</a></details>`:`<strong>${catalogError?'No se pudo cargar UCDP.':'Cargando catálogo UCDP…'}</strong>${catalogError?'<button id="retry-catalog">Reintentar</button>':''}`;const retry=$('retry-catalog');if(retry)retry.onclick=loadCatalog;return;}
  const rows=mode==='climate'?state.events:state.newsEvents;const dates=rows.map(e=>e.date).filter(Boolean).sort();
  $('map-legend').textContent=mode==='climate'?'● Verde: NASA EONET · naranja: sismos USGS':'● Violeta: lugares reconocidos en noticias';
  $('map-coverage').innerHTML=mode==='climate'?`<strong>Clima y eventos naturales</strong><p>Fechas de observación: ${dates.length?esc(date(dates[0]))+' — '+esc(date(dates.at(-1))):'consultando registros'}.</p><p>NASA EONET: catálogo global, últimos 30 días, hasta 100 eventos; última posición puntual, no área afectada ni pronóstico. USGS: sismos ≥ 2,5, últimos 7 días; son geológicos, no climáticos.</p>${state.sources.map(s=>`<p>${sourceLink(s.docs,s.name)} · ${esc(s.status==='ok'?'Conectada':'No disponible')} · consulta ${esc(date(s.checkedAt))} · ${s.count} registros.</p>`).join('')}${!state.sources.length?'<p>Consultando fuentes…</p>':''}`:`<strong>Noticias · fuentes públicas del feed</strong><p>${rows.length} noticias cargadas. Cobertura limitada a los medios y filtros del feed. Ubicación aproximada reconocida en el titular, no confirmación del lugar del hecho. Las noticias sin ubicación permanecen en la lista.</p><p>Última consulta de titulares: ${rows.length?esc(date(rows.map(e=>e.capturedAt).filter(Boolean).sort().at(-1))):'sin consulta disponible'}.</p><p>Publicaciones: ${dates.length?esc(date(dates[0]))+' — '+esc(date(dates.at(-1))):'sin registros disponibles'}.</p><button id="map-open-feed">Buscar más noticias en el feed</button>`;
  const feed=$('map-open-feed');if(feed)feed.onclick=()=>document.querySelector('.bottom-ribbon [data-view="feed"]').click();
 }
 function rows(){if(mode==='conflicts'&&warView==='reports'){const q=fold($('map-query').value);return reports.rows.filter(e=>fold(e.title+' '+e.source+' '+(e.location?.label||'')).includes(q)&&($('map-category').value==='all'||($('map-category').value==='confirmed'?!!e.verification:!e.verification)));}const result=selectMapRows(mode,{...state,conflicts:(warView==='events'?catalog?.incidents:catalog?.conflicts)||[]},$('map-query').value,$('map-category').value||'all',Number($('period').value));return mode==='conflicts'?(warView==='events'?result.filter(e=>(!$('war-from').value||e.end>=$('war-from').value)&&(!$('war-until').value||e.start<=$('war-until').value)).sort((a,b)=>b.end.localeCompare(a.end)):result.sort((a,b)=>b.count-a.count)):result;}
 function render(){
  for(const id of ['war-from','war-until'])$(id).closest('label').hidden=warView==='reports';
  const list=rows();dotLayer.clearLayers();const located=list.filter(e=>e.coordinates);$('count').textContent=`${located.length} puntos · ${list.length-located.length} sin ubicación`;
  $('map-results').textContent=mode==='conflicts'&&warView==='reports'&&reports.loading&&!reports.rows.length?'Buscando reportes recientes…':mode==='conflicts'&&warView!=='reports'&&!catalog?(catalogError?'Catálogo no disponible.':'Cargando conflictos…'):`${list.length} resultados${list.length>limit?` · mostrando ${limit}`:''}`;
  $('map-list').innerHTML=list.slice(0,limit).map(e=>`<button class="map-result ${selected?.id===e.id?'selected':''}" data-map-id="${esc(e.id)}"><span>${esc(mode==='conflicts'&&warView!=='reports'?countryName(e.country):e.source)}</span><strong>${esc((mode==='conflicts'&&warView==='events'?e.place+' · '+e.title:e.title).replace(/XXX\d+/g,'Actor sin identificar'))}</strong><small>${mode==='conflicts'&&warView==='reports'?(e.verification?'Confirmado':'Reporte preliminar')+' · '+esc(date(e.date)):mode==='conflicts'?esc(violenceTypes[e.type])+' · '+(warView==='events'?esc(e.end):e.count+(e.count===1?' registro':' registros')):esc(date(e.date))}</small></button>`).join('')+(list.length>limit?'<button id="map-more">Mostrar más</button>':'')+(!list.length&&!(mode==='conflicts'&&!catalog)?'<p class="empty">Sin registros para estos filtros.</p>':'');
  $('map-list').querySelectorAll('[data-map-id]').forEach(b=>b.onclick=()=>choose(list.find(e=>e.id===b.dataset.mapId)));const more=$('map-more');if(more)more.onclick=()=>{limit+=50;render()};
  for(const e of located){const color=mode==='conflicts'&&warView==='reports'?(e.verification?'#087c70':'#bd7a24'):mode==='conflicts'?({'1':'#b75155','2':'#bf842d','3':'#8e5898'}[e.type]):mode==='news'?'#7255ab':e.provider==='usgs'?'#bf753b':'#167f72';const tip=document.createElement('span');tip.textContent=mode==='conflicts'?countryName(e.country)+' · '+e.title:e.title;L.circleMarker([e.coordinates[1],e.coordinates[0]],{renderer:canvas,radius:mode==='conflicts'&&warView==='groups'?Math.min(11,5+Math.log2(e.count+1)/2):5,color:'#fff',weight:1.5,fillColor:color,fillOpacity:.85}).bindTooltip(tip).addTo(dotLayer).on('click',()=>choose(e));}
  coverage();
 }
 function choose(e){if(!e)return;selected=e;if(matchMedia('(max-width:900px)').matches)catalogDetails.open=false;
  if(mode==='conflicts'&&warView==='reports'){control.setEnabled(false);control.panel.hidden=true;reports.choose(e);render();return;}
  if(mode==='conflicts'&&warView==='events'){chooseIncident(e);render();return;}
  const conflict=mode==='conflicts',isUkraine=conflict&&e.country==='Ukraine';control.setEnabled(false);control.panel.hidden=!isUkraine;
  if(conflict){map.invalidateSize();const [[south,west],[north,east]]=e.bounds; if(north-south<.01&&east-west<.01)map.setView([e.coordinates[1],e.coordinates[0]],5);else map.fitBounds(e.bounds,{padding:[35,35],maxZoom:7});}
  else if(e.coordinates)map.setView([e.coordinates[1],e.coordinates[0]],Math.max(4,map.getZoom()));
  $('map-context').innerHTML=`<span class="eyebrow">${esc(conflict?countryName(e.country):e.source)}</span><h2>${esc(e.title)}</h2>${conflict?`<p>${esc(violenceTypes[e.type])}. UCDP registra ${e.count} eventos candidatos en este país y agrupación durante el periodo publicado.</p><p><strong>Actores según la fuente</strong><br>${e.actors.map(esc).join(' · ')}</p><dl><dt>Fechas de los registros</dt><dd>${esc(e.start)} — ${esc(e.end)}</dd><dt>Estado</dt><dd>Preliminar${e.review?` · ${e.review} registros requieren revisión según UCDP`:''}. No implica actividad actual.</dd><dt>Ubicación</dt><dd>Centro de registros agregados; no posición militar ni frontera.</dd></dl><p>${sourceLink(catalog.metadata.docs,'Consultar UCDP y definiciones')} · ${sourceLink(catalog.metadata.url,'CSV original')}</p>${!isUkraine?'<p class="map-note">Esta capa no incluye polígonos de control territorial para este conflicto.</p>':''}`:`<p>${esc(e.detail||'Noticia publicada por '+e.source+'. Abre la síntesis para consultar contexto y fuentes.')}</p><dl><dt>Fecha del registro</dt><dd>${esc(date(e.date))}</dd><dt>Ubicación</dt><dd>${esc(e.provider==='news'?(e.location?.label||'Sin ubicación identificable')+' · aproximada, reconocida en el titular':e.coordinates.join(', ')+' · última posición puntual')}</dd></dl><p>${sourceLink(/^https:\/\//.test(e.url)?e.url:'https://eonet.gsfc.nasa.gov/', 'Publicación original')}</p>`}<div class="map-context-actions">${conflict?'':`<button id="map-read">${e.provider==='news'?'Leer síntesis':'Ver detalles y referencias'}</button>`}<button id="map-investigate" class="primary">＋ Añadir a investigación</button></div>`;
  $('map-investigate').onclick=()=>addEvidence(conflict?{id:e.id,title:countryName(e.country)+' · '+e.title,date:e.end+'T00:00:00Z',provider:'ucdp',source:'UCDP Candidate '+catalog.metadata.version,category:violenceTypes[e.type],coordinates:e.coordinates,url:catalog.metadata.docs,detail:`${e.count} registros candidatos, ${e.start} — ${e.end}. Actores: ${e.actors.join('; ')}. ${catalog.metadata.method}`,capturedAt:catalog.metadata.retrievedAt}:e);
  const read=$('map-read');if(read)read.onclick=()=>e.provider==='news'?readNews(e):openEvent(e);
  if(isUkraine)control.setEnabled(true);
  render();if(matchMedia('(max-width: 900px)').matches)$('map-context').scrollIntoView({behavior:'smooth',block:'start'});
 }
 function chooseIncident(e){
  const isUkraine=e.country==='Ukraine';control.setEnabled(false);control.panel.hidden=!isUkraine;if(isUkraine)control.setEnabled(true);map.setView([e.coordinates[1],e.coordinates[0]],6);
  const precision={1:'Localidad identificada por la fuente',2:'En torno a una localidad (hasta 25 km)',3:'División administrativa de segundo nivel',4:'División administrativa de primer nivel',5:'País',6:'Lugar no especificado',7:'Mar o espacio aéreo'};
  $('map-context').innerHTML=`<span class="eyebrow">EVENTO DOCUMENTADO · PRELIMINAR</span><h2>${esc(countryName(e.country))} · ${esc(e.place)}</h2><p>${esc(violenceTypes[e.type])}</p><details><summary>Qué reportaron las fuentes</summary><p>${esc(e.sourceArticle||'Referencia disponible en el registro original UCDP.')}</p></details><p>${e.actors.map(esc).join(' · ')}</p><dl><dt>Fecha del hecho según UCDP</dt><dd>${esc(e.start)}${e.start!==e.end?' — '+esc(e.end):''}</dd><dt>Precisión temporal</dt><dd>${e.datePrecision===1?'Día identificado':'Intervalo estimado por la fuente; no fecha exacta'}</dd><dt>Precisión geográfica</dt><dd>${esc(precision[e.wherePrecision]||'Según registro original')} · el punto no indica una posición militar actual.</dd><dt>Fuentes citadas en el registro</dt><dd>${esc(e.sourceOffice||e.sourceArticle||'Consultar registro UCDP')}</dd></dl><p>${sourceLink(catalog.metadata.url,'Descargar registros originales UCDP')} · ID ${esc(e.id)}</p><p class="map-note">UCDP clasifica violencia organizada. Este registro no especifica por sí solo el tipo de arma o ataque.</p><button id="map-investigate" class="primary">＋ Añadir a investigación</button>`;
  $('map-investigate').onclick=()=>addEvidence({...e,provider:'ucdp',source:'UCDP Candidate',category:violenceTypes[e.type],url:catalog.metadata.docs,detail:`${e.start} — ${e.end}. ${e.actors.join('; ')}. ${e.sourceOffice}. Precisión geográfica UCDP: ${e.wherePrecision}. Preliminar.`,capturedAt:catalog.metadata.retrievedAt});
  if(matchMedia('(max-width:900px)').matches)$('map-context').scrollIntoView({behavior:'smooth'});
 }
 async function loadCatalog(){if(loading)return;loading=true;catalogError=false;coverage();try{const r=await fetch('/data/conflict-catalog.json',{cache:'no-cache',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const d=await r.json();if(!Array.isArray(d.conflicts)||!d.metadata?.periodEnd)throw Error();if(catalog&&d.metadata.periodEnd<catalog.metadata.periodEnd)throw Error();const followsLatest=!catalog||$('war-until').value===catalog.metadata.lastEventEnd;catalog=d;if(followsLatest||!$('war-until').value)$('war-until').value=d.metadata.lastEventEnd;if(!$('war-from').value)$('war-from').value=new Date(Date.parse(d.metadata.lastEventEnd)-30*86400000).toISOString().slice(0,10);}catch{catalogError=true;}finally{loading=false;if(mode==='conflicts')render();}}
 function world(){map.invalidateSize();map.fitBounds([[-58,-175],[78,175]],{padding:[8,8],maxZoom:2});}
 $('world').onclick=world;
 function setMode(next){if(!['conflicts','climate','news'].includes(next))return;mode=next;warTools.hidden=mode!=='conflicts';selected=null;limit=50;$('map-query').value='';$('map-category').value='all';control.setEnabled(false);control.panel.hidden=true;document.querySelectorAll('[data-map-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mapMode===mode);b.setAttribute('aria-pressed',b.dataset.mapMode===mode)});$('map-catalog-title').textContent={conflicts:'Explorar conflictos',climate:'Eventos naturales',news:'Noticias en el mapa'}[mode];$('map-period-label').hidden=mode==='conflicts';$('map-context').innerHTML='<span class="eyebrow">CONTEXTO Y FUENTES</span><h2>Explora el territorio</h2><p>Selecciona un punto o un registro para revisar su fecha, contexto y procedencia.</p>';$('panorama').dataset.mapMode=mode;setCategories();world();render();if(mode==='conflicts'){if(warView==='reports')reports.load();else loadCatalog();}}
 $('map-query').oninput=()=>{limit=50;render()};$('map-category').onchange=()=>{limit=50;render()};$('period').onchange=render;document.querySelectorAll('[data-map-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mapMode));
 $('map-base').onchange=()=>{const kind=$('map-base').value;const specs={street:['https://tile.openstreetmap.org/{z}/{x}/{y}.png','© OpenStreetMap contributors',19],relief:['https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png','© OpenStreetMap · SRTM | OpenTopoMap (CC-BY-SA)',17],satellite:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}','Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics and GIS User Community',18]};map.removeLayer(tile);const [url,attribution,maxZoom]=specs[kind];tile=L.tileLayer(url,{attribution,maxZoom}).addTo(map);tile.bringToBack();$('map-base-status').textContent=kind==='satellite'?'Mosaico satelital de distintas fechas; no es una imagen en tiempo real.':kind==='relief'?'Relieve OpenTopoMap · cobertura según disponibilidad de teselas.':'Cartografía OpenStreetMap · actualización variable por zona.';tile.on('tileerror',()=>{$('map-base-status').textContent='Algunas teselas no están disponibles. Puedes cambiar a Cartografía; los registros siguen en el catálogo.';});};
 new ResizeObserver(()=>map.invalidateSize({pan:false})).observe(map.getContainer());setMode('conflicts');setInterval(()=>{if(!document.hidden)loadCatalog()},300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadCatalog()});
 return {setMode,update(data){state=data;setCategories();render();}};
}
